css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; }
.dcx a{ color: #0B7A45; text-decoration: none; }
.dcx a:hover{ color: #0A6A3C; }
.dcx :focus-visible{ outline: 2px solid #0FA45B; outline-offset: 3px; }
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover{ display: block; }
.dcx [data-burger]{ display: none; }
.dcx details > summary{ list-style: none; cursor: pointer; }
.dcx details > summary::-webkit-details-marker{ display: none; }
.dcx details[open] [data-plus]{ transform: rotate(45deg); }
@media (max-width: 1100px){.dcx [data-quote]{ position: static !important; width: 100% !important; max-width: none !important; margin-top: 14px !important; }
.dcx [data-quotewrap]{ padding-bottom: 0 !important; }
.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-two],.dcx [data-three]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-rail]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-cards]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 38px !important; }
.dcx [data-h2]{ font-size: 30px !important; }
.dcx [data-hand]{ display: none !important; }
.dcx [data-faq]{ grid-template-columns: minmax(0,1fr) !important; }
}
@media (max-width: 640px){.dcx [data-rail],.dcx [data-statgrid]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 31px !important; }
.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
.dcx [data-footcols]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
}
